int
device_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
               int *eofp, caller_context_t *ct_unused, int flags_unused)
{
    int error = 0;
    struct dirent *dent;
    char *dir_path = NULL;
    int namelen;
    int end_of_file = 0;

    if (uiop->uio_resid < sizeof(struct dirent))
        return 0;

    dent = (struct dirent *)uiop->uio_iov->iov_base;

    /* Check for the special ZVOL_DIR path */
    if (strcmp(dvp->v_path, ZVOL_DIR) == 0) {
        if (create_required_directories(dvp, cred) != 0)
            return EINVAL;
    }

    /* Acquire a read lock to ensure thread safety */
    read_lock(&dvp->v_rwlock);

    while (!end_of_file) {
        namelen = get_next_dataset_name(dvp, dent->d_name, MAXNAMLEN);

        if (namelen <= 0) {
            end_of_file = 1;
            break;
        }

        dent->d_reclen = sizeof(struct dirent) + namelen;
        dent->d_namlen = namelen;

        if (uiop->uio_resid < dent->d_reclen) {
            error = EFAULT;
            break;
        }

        if (uio_write(dent->d_reclen, uiop) != 0) {
            error = EFAULT;
            break;
        }
    }

    /* Release the read lock */
    read_unlock(&dvp->v_rwlock);

    *eofp = end_of_file;
    return error;
}

