int
device_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
               int *eofp, caller_context_t *ct_unused, int flags_unused)
{
    char *path;
    int error = 0;
    struct dirent *dent;
    int done = 0;

    *eofp = 0;

    if ((error = get_dir_path(dvp, &path))) {
        return error;
    }

    if (strcmp(path, ZVOL_DIR) == 0) {
        if ((error = handle_zvol_directory(dvp, uiop, &done))) {
            kfree(path);
            return error;
        }
    } else {
        if ((error = iterate_datasets(dvp, path, uiop, &done))) {
            kfree(path);
            return error;
        }
    }

    kfree(path);

    if (done)
        *eofp = 1;

    return 0;
}

int
vdev_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
    int *eofp, caller_context_t *ct_unused, int flags_unused)
{
    int error = 0;
    struct dirent *dent = NULL;
    size_t bpos;
    off_t offset = uiop->uio_offset;
    size_t count = uiop->uio_resid;
    size_t reclen;

    if (offset == 0) {
        /* Handle initial directory entry */
        dent = kmem_alloc(sizeof(struct dirent), KM_SLEEP);
        dent->d_ino = 1;
        dent->d_type = DT_DIR;
        dent->d_namlen = 1;
        dent->d_name[0] = '.';
        dent->d_name[1] = '\0';
        reclen = uiop->uio_segflg == UIO_USERSPACE ?
            UIO_MXBUFSIZE : sizeof(struct dirent);
        error = uiomove(dent, reclen, UIO_WRITE, uiop);
        if (error != 0) {
            kmem_free(dent, sizeof(struct dirent));
            return error;
        }
    }

    if (uiop->uio_offset < 0)
        return EINVAL;

    while (uiop->uio_resid > 0) {
        dent = kmem_alloc(sizeof(struct dirent), KM_SLEEP);
        dent->d_ino = 2;
        dent->d_type = DT_DIR;
        dent->d_namlen = 1;
        dent->d_name[0] = '.';
        dent->d_name[1] = '\0';
        reclen = uiop->uio_segflg == UIO_USERSPACE ?
            UIO_MXBUFSIZE : sizeof(struct dirent);
        error = uiomove(dent, reclen, UIO_WRITE, uiop);
        if (error != 0) {
            kmem_free(dent, sizeof(struct dirent));
            break;
        }
    }

    *eofp = 1;

    if (dent != NULL)
        kmem_free(dent, sizeof(struct dirent));

    return error;
}

int dev_readdir(struct vnode *dvp, struct uio *uiop, struct cred *cred,
                int *eofp, caller_context_t *ct_unused, int flags_unused) {
    *eofp = 0;

    // Check if the directory is a special device node (ZVOL_DIR)
    if (strcmp(dvp->v_data, ZVOL_DIR) == 0) {
        // Acquire read lock for thread safety
        rw_rdlock(&zvol_rwlock);

        // Iterate over datasets and populate directory entries
        dataset_t *ds;
        LIST_FOREACH(ds, &dataset_list, link) {
            struct dirent *dent;
            int error;

            dent = (struct dirent *)malloc(sizeof(*dent));
            if (dent == NULL) {
                rw_runlock(&zvol_rwlock);
                return ENOMEM;
            }

            snprintf(dent->d_name, sizeof(dent->d_name), "%s", ds->name);
            dent->d_ino = ds->ino;
            dent->d_type = DT_DIR;

            error = uiomove(dent, sizeof(*dent), uiop);
            if (error != 0) {
                free(dent);
                rw_runlock(&zvol_rwlock);
                return error;
            }

            if (uiop->uio_resid == 0) {
                *eofp = 1;
                free(dent);
                break;
            }
        }

        // Release read lock
        rw_runlock(&zvol_rwlock);
        return 0;
    }

    // For other directories, return ENOTSUP
    return ENOTSUP;
}
